$ErrorActionPreference = "Stop"
$Repo = Join-Path $HOME "Intellect-Media"
$Python = Join-Path $Repo ".venv\Scripts\python.exe"

if (-not (Test-Path $Repo)) { throw "Intellect-Media repository not found: $Repo" }
if (-not (Test-Path $Python)) { throw "Python environment not found: $Python" }

Set-Location $Repo
$Encoded = ""
$Items = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Encoded)) | ConvertFrom-Json -AsHashtable

foreach ($Item in $Items.GetEnumerator()) {
    $Path = Join-Path $Repo $Item.Key
    $Parent = Split-Path $Path -Parent
    New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    [IO.File]::WriteAllText($Path, [string]$Item.Value, [Text.UTF8Encoding]::new($false))
}

& $Python "foundation_block2.py"
if ($LASTEXITCODE -ne 0) { throw "Foundation Block 2 execution failed." }

& $Python "tests/test_foundation_block2.py"
if ($LASTEXITCODE -ne 0) { throw "Foundation Block 2 verification failed." }

Remove-Item "foundation_block2.py" -Force

Write-Host ""
Write-Host "=== FOUNDATION BLOCK 2 VERIFIED ===" -ForegroundColor Green
git status --short
